/* ===== Ant Design — 100 native facets (data-spectrum="antd"). Token-driven, self-contained. ===== */
.antd-root{--antd-radius:6px;--antd-font:-apple-system, "Segoe UI", system-ui, Roboto, "Helvetica Neue", Arial, sans-serif;font-family:var(--antd-font,inherit)}
@keyframes antdBtnPulse{0%,100%{box-shadow:0 0 0 0 rgba(var(--_rgb),.5)}50%{box-shadow:0 0 0 6px rgba(var(--_rgb),0)}}
.antd-btn{display:inline-flex;align-items:center;gap:8px;padding:9px 18px;border-radius:var(--antd-radius,999px);background:var(--_c);color:#fff;font-weight:700;border:0;animation:antdBtnPulse 2.4s ease-in-out infinite}
@keyframes antdTgKnob{0%,100%{left:2px}50%{left:20px}}
.antd-toggle{position:relative;width:44px;height:24px;border-radius:999px;background:rgba(var(--_rgb),.28);border:1px solid rgba(var(--_rgb),.5)}
.antd-toggle::after{content:"";position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.7);animation:antdTgKnob 2.6s ease-in-out infinite}
@keyframes antdChipShine{0%{background-position:-160% 0}60%,100%{background-position:260% 0}}
.antd-chip{position:relative;overflow:hidden;display:inline-flex;align-items:center;padding:4px 12px;border-radius:999px;background:rgba(var(--_rgb),.16);border:1px solid rgba(var(--_rgb),.4);color:var(--_c);font-size:12px;font-weight:700}
.antd-chip::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 40%,rgba(var(--_rgb),.4) 50%,transparent 60%);background-size:250% 100%;animation:antdChipShine 3s linear infinite;pointer-events:none}
@keyframes antdMenuSel{0%,100%{background:rgba(var(--_rgb),.12)}50%{background:rgba(var(--_rgb),.26)}}
.antd-menu{min-width:150px;padding:6px;border-radius:var(--antd-radius,12px);background:var(--panel2);border:1px solid var(--line)}
.antd-menu .antd-mi{padding:7px 10px;border-radius:8px;color:var(--ink);font-size:12px}
.antd-menu .antd-sel{color:var(--_c);animation:antdMenuSel 2.8s ease-in-out infinite}
@keyframes antdNotifIn{0%,100%{transform:translateX(-6px);opacity:.75}50%{transform:translateX(0);opacity:1}}
.antd-toast{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:var(--panel2);border:1px solid var(--line);border-left:3px solid var(--_c);color:var(--ink);font-size:12px;animation:antdNotifIn 3s ease-in-out infinite}
.antd-toast::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.8)}
@keyframes antdCalloutEdge{0%{transform:translateX(-120%)}100%{transform:translateX(120%)}}
.antd-callout{position:relative;overflow:hidden;padding:10px 14px;border-radius:10px;background:rgba(var(--_rgb),.1);border:1px solid rgba(var(--_rgb),.35);color:var(--ink);font-size:12px}
.antd-callout::after{content:"";position:absolute;top:0;left:0;height:2px;width:60%;background:linear-gradient(90deg,transparent,var(--_c),transparent);animation:antdCalloutEdge 2.6s linear infinite;pointer-events:none}
@keyframes antdBarGrow{0%{transform:scaleY(.25)}50%{transform:scaleY(1)}100%{transform:scaleY(.25)}}
.antd-chart{display:flex;align-items:flex-end;gap:5px;height:44px;padding:6px 8px;border-radius:10px;background:var(--panel2);border:1px solid var(--line)}
.antd-chart i{flex:1;background:var(--_c);border-radius:3px 3px 0 0;transform-origin:bottom;animation:antdBarGrow 2.4s ease-in-out infinite}
.antd-chart i:nth-child(2){animation-delay:.2s}.antd-chart i:nth-child(3){animation-delay:.4s}.antd-chart i:nth-child(4){animation-delay:.6s}
@keyframes antdInputCaret{0%,49%{opacity:1}50%,100%{opacity:0}}
.antd-field{display:inline-flex;align-items:center;gap:2px;min-width:150px;padding:8px 11px;border-radius:10px;background:var(--panel);border:1px solid var(--_c);box-shadow:0 0 0 3px rgba(var(--_rgb),.18);color:var(--ink);font-size:12px}
.antd-field .antd-caret{width:1.5px;height:14px;background:var(--_c);animation:antdInputCaret 1.1s step-end infinite}
@keyframes antdProg{0%{width:8%}80%,100%{width:96%}}
.antd-prog{width:150px;height:8px;border-radius:999px;background:rgba(var(--_rgb),.18);overflow:hidden}
.antd-prog i{display:block;height:100%;border-radius:inherit;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:antdProg 3s ease-in-out infinite}
@keyframes antdAvRing{to{transform:rotate(1turn)}}
.antd-avatar{position:relative;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:var(--panel2);color:var(--ink);font-weight:800}
.antd-avatar::before{content:"";position:absolute;inset:-3px;border-radius:50%;background:conic-gradient(from 0deg,var(--_c),transparent 55%,var(--_c));-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 3px));animation:antdAvRing 3.4s linear infinite}
@keyframes antdBadgePop{0%,100%{transform:scale(1)}30%{transform:scale(1.25)}}
.antd-badge{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--_c);color:#fff;font-size:11px;font-weight:800;animation:antdBadgePop 2s ease-in-out infinite}
@keyframes antdTabSlide{0%,100%{left:2px}50%{left:calc(50% + 1px)}}
.antd-tabs{position:relative;display:inline-flex;padding:3px;border-radius:999px;background:var(--panel2);border:1px solid var(--line)}
.antd-tabs span{position:relative;z-index:1;padding:5px 14px;font-size:12px;color:var(--ink)}
.antd-tabs::before{content:"";position:absolute;top:3px;bottom:3px;width:calc(50% - 3px);left:2px;border-radius:999px;background:rgba(var(--_rgb),.9);animation:antdTabSlide 3.2s ease-in-out infinite}
@keyframes antdTipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.antd-tip{display:inline-block;padding:6px 10px;border-radius:8px;background:var(--panel2);border:1px solid var(--_c);color:var(--ink);font-size:11px;box-shadow:0 4px 14px rgba(var(--_rgb),.3);animation:antdTipFloat 2.6s ease-in-out infinite}
@keyframes antdSpin{to{transform:rotate(1turn)}}
.antd-spinner{width:26px;height:26px;border-radius:50%;border:3px solid rgba(var(--_rgb),.22);border-top-color:var(--_c);animation:antdSpin 1s linear infinite}
@keyframes antdCardGlow{0%,100%{box-shadow:0 0 0 1px var(--line)}50%{box-shadow:0 0 16px rgba(var(--_rgb),.4)}}
.antd-card{width:150px;padding:12px;border-radius:var(--antd-radius,12px);background:var(--card);color:var(--ink);animation:antdCardGlow 3.4s ease-in-out infinite}
.antd-card b{color:var(--_c);font-size:12px}.antd-card p{margin:4px 0 0;font-size:11px;color:var(--muted)}
@keyframes antdCheckIn{0%,20%{clip-path:inset(0 100% 0 0)}60%,100%{clip-path:inset(0 0 0 0)}}
.antd-check{position:relative;width:22px;height:22px;border-radius:6px;background:var(--_c);display:grid;place-items:center}
.antd-check::after{content:"✓";color:#fff;font-size:14px;font-weight:900;animation:antdCheckIn 2.4s ease-in-out infinite}
@keyframes antdSliderThumb{0%,100%{left:2px}50%{left:calc(100% - 16px)}}
.antd-slider{position:relative;width:150px;height:6px;border-radius:999px;background:rgba(var(--_rgb),.2)}
.antd-slider::before{content:"";position:absolute;top:-5px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--_c);box-shadow:0 0 8px rgba(var(--_rgb),.6);animation:antdSliderThumb 3s ease-in-out infinite}
@media(prefers-reduced-motion:reduce){.antd-root [class*="antd-"],.antd-root [class*="antd-"]::before,.antd-root [class*="antd-"]::after,.antd-root [class],.antd-root [class]::before,.antd-root [class]::after{animation:none!important}}

